[
  {
    "qid": "0005-t2i-1",
    "sample_id": "0005_亮剑_674d386c.webp",
    "task": "t2i",
    "knowledge_dim": "history_event",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "画面呈现四位人物的半身肖像，中央人物最突出",
        "中央人物穿黄褐色制服并戴带红五星的帽子",
        "左侧人物包含一名蓝灰色制服男性与一名女性",
        "右侧人物穿深蓝色制服并戴大檐帽",
        "背景具有战争硝烟、飞机剪影和黄褐色调"
      ],
      "anchor_features": [
        "电视剧《亮剑》的核心人物群像",
        "李云龙的黄褐色八路军形象与刚毅面容",
        "楚云飞的深蓝色国民党军官形象与大檐帽",
        "抗战时期中国战场的指挥与对峙氛围"
      ],
      "trigger_check": "能：提示词明确给出李云龙、楚云飞、作品语境和抗战时期战地会面，足以触发两位角色的阵营与形制知识。",
      "counterexample_test": "无法构造：若将任一角色改成另一阵营的服装体系，便不再符合角色身份与作品中的视觉锚点。"
    },
    "gen_prompt": "写实电视剧剧照风格，以《亮剑》中的李云龙与楚云飞为主体：两人在抗战时期的黄土高坡临时指挥所短暂会面，远处有炮火、烟尘和低空飞行的战机，李云龙站在画面左前方，楚云飞站在右前方，二人神情克制而警觉，后景安排两名战友与木桌地图，整体采用黄褐色胶片色调、强烈侧光和浅景深，画面与宣传海报构图明显不同。",
    "implicit_checks": [
      {
        "check": "李云龙呈现八路军制式的灰土色上衣，并佩戴缀有红五星的软军帽",
        "knowledge": "[solid] 《亮剑》中李云龙的角色身份是八路军独立团团长，其典型视觉形象采用灰土色八路军制服与红五星软军帽。",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "李云龙缺席，或人物被画成现代军人、便装人物或其他阵营形象",
          "1": "人物身份基本可辨，但制服颜色、帽式或红五星标志至少有一项明显错误",
          "2": "李云龙身份清楚，灰土色制服、软军帽和红五星标志同时准确呈现"
        },
        "acceptable_variants": [
          "人物被烟尘或侧身角度部分遮挡，但红五星与灰土色上衣仍清楚可辨",
          "制服因黄褐色胶片调色略偏棕灰，但整体制式特征保持准确"
        ]
      },
      {
        "check": "楚云飞呈现深蓝色国民党军官制服，并佩戴大檐帽及军官标志",
        "knowledge": "[solid] 《亮剑》中楚云飞是晋绥军358团团长，典型形象为深蓝色国民党军官制服、大檐帽及金黄色军官标志。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "楚云飞缺席，或被画成八路军制服、现代军服或普通士兵形象",
          "1": "楚云飞人物可辨，但深蓝色制服、大檐帽或军官标志存在明显缺失",
          "2": "楚云飞身份清楚，深蓝制服、大檐帽与军官标志组合完整且位置自然"
        },
        "acceptable_variants": [
          "大檐帽因人物侧身或构图裁切只露出部分，但帽檐与深蓝色制式仍可辨",
          "金黄色标志被光线弱化，但肩部或领部仍保留军官装饰"
        ]
      },
      {
        "check": "两位人物的阵营身份通过两套不同的制服体系形成清晰视觉区分",
        "knowledge": "[solid] 抗战时期八路军与国民党军具有不同的制服、帽式和标志体系；李云龙与楚云飞同框时应保留这种身份对照。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "两人穿着完全相同，或身份服装混用到无法区分所属阵营",
          "1": "两人存在颜色差异，但帽式、标志或制服结构混乱，阵营区分不稳定",
          "2": "一人保持灰土色红五星体系，另一人保持深蓝大檐帽体系，身份对照一眼可辨"
        },
        "acceptable_variants": [
          "两人被前景烟尘部分遮挡，但不同色系和帽式仍形成明确区分",
          "采用逆光剪影表现，只要两套帽式与制服轮廓保持可辨"
        ]
      }
    ],
    "facet_tags": [
      "character_likeness",
      "cultural_elements",
      "composition",
      "lighting_atmosphere"
    ],
    "gate_spec": {
      "required_subjects": [
        "李云龙",
        "楚云飞"
      ],
      "theme_definition": "《亮剑》两位核心指挥官在抗战时期战地指挥所短暂会面的写实剧照场景"
    },
    "expected_failure_modes": [
      "将楚云飞误画成与李云龙相同的八路军制服和红五星帽",
      "把李云龙画成深蓝色大檐帽军官，混淆两人的阵营身份",
      "使用现代突击步枪、现代迷彩服或现代军事指挥设备，破坏抗战年代场景"
    ],
    "notes": "利用李云龙与楚云飞的角色阵营和服制差异，测试模型对《亮剑》人物视觉身份的知识召回与组合呈现能力。"
  }
]
